  left: 0;
  bottom: -0.2rem;
  width: 100%;
  height: 1px;
  background: var(--text);
  transform: scaleX(0);
  transform-origin: right;
  transition: transform 0.25s ease;
}
.nav-links a:hover::after,
.nav-links a[aria-current='page']::after {
  transform: scaleX(1);
  transform-origin: left;
}

.menu-toggle {
  display: none;
  width: 2.4rem;
  height: 2.4rem;
  border: 0;
  background: transparent;
  cursor: pointer;
  position: relative;
  z-index: 1200;
}
.menu-toggle span,
.menu-toggle span::before,
.menu-toggle span::after {
  display: block;
  width: 1.5rem;
  height: 1px;
  background: var(--text);
  position: absolute;
  left: 0.45rem;
  transition: transform 0.3s ease, opacity 0.3s ease;
}
.menu-toggle span { top: 1.15rem; }
.menu-toggle span::before,
.menu-toggle span::after { content: ''; }
.menu-toggle span::before { transform: translateY(-0.45rem); }
.menu-toggle span::after { transform: translateY(0.45rem); }

.menu-toggle[aria-expanded='true'] span { background: transparent; }
.menu-toggle[aria-expanded='true'] span::before { transform: rotate(45deg); }
.menu-toggle[aria-expanded='true'] span::after { transform: rotate(-45deg); }

