  --bg-alt: #efe9e1;
  --text: #1a1a1a;
  --muted: #5f5851;
  --line: #d8cdc0;
  --accent-terracotta: #c7876f;
  --accent-sage: #9aa48f;
  --accent-sand: #cdb89f;
  --accent-clay: #af7f62;
  --max-width: 1240px;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  background: var(--bg);
  color: var(--text);
  font-family: 'Inter', system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  line-height: 1.65;
}

a { color: inherit; text-decoration: none; }

.site-wrap { width: min(100%, var(--max-width)); margin: 0 auto; padding: 0 2rem 4rem; }

.site-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 2rem 0;
  position: relative;
}

.logo {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: clamp(1.2rem, 1.8vw, 1.6rem);
  font-weight: 700;
  letter-spacing: 0.02em;
}

.nav-links { display: flex; gap: 1.8rem; font-size: 0.95rem; }
.nav-links a { position: relative; }
.nav-links a::after {
  content: '';
  position: absolute;
  left: 0;
  bottom: -0.2rem;
  width: 100%;
  height: 1px;
  background: var(--text);
  transform: scaleX(0);
  transform-origin: right;
  transition: transform 0.25s ease;
}
.nav-links a:hover::after,
.nav-links a[aria-current='page']::after {
  transform: scaleX(1);
  transform-origin: left;
}

.menu-toggle {
  display: none;
  width: 2.4rem;
  height: 2.4rem;
  border: 0;
  background: transparent;
  cursor: pointer;
  position: relative;
  z-index: 1200;
}
.menu-toggle span,
.menu-toggle span::before,
.menu-toggle span::after {
  display: block;
  width: 1.5rem;
  height: 1px;
  background: var(--text);
  position: absolute;
  left: 0.45rem;
  transition: transform 0.3s ease, opacity 0.3s ease;
}
.menu-toggle span { top: 1.15rem; }
.menu-toggle span::before,
.menu-toggle span::after { content: ''; }
.menu-toggle span::before { transform: translateY(-0.45rem); }
.menu-toggle span::after { transform: translateY(0.45rem); }

.menu-toggle[aria-expanded='true'] span { background: transparent; }
.menu-toggle[aria-expanded='true'] span::before { transform: rotate(45deg); }
.menu-toggle[aria-expanded='true'] span::after { transform: rotate(-45deg); }

.mobile-overlay {
  position: fixed;
  inset: 0;
  background: var(--bg);
  display: grid;
  place-items: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease;
  z-index: 1100;
}
.mobile-overlay.open { opacity: 1; pointer-events: auto; }
.mobile-overlay nav { display: grid; gap: 1.2rem; text-align: center; }
.mobile-overlay a {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: clamp(1.8rem, 8vw, 3rem);
  line-height: 1.05;
}

.hero {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 4rem;
  align-items: end;
  margin: 4.5rem 0 7rem;
}

.eyebrow { font-size: 0.85rem; letter-spacing: 0.11em; text-transform: uppercase; color: var(--muted); }

h1, h2, h3 {
  font-family: 'Playfair Display', Georgia, serif;
  line-height: 0.98;
  margin: 0;
}

.hero h1 { font-size: clamp(2.8rem, 9vw, 7rem); margin-top: 0.9rem; }
.hero p { max-width: 34rem; color: var(--muted); font-size: clamp(1rem, 1.5vw, 1.2rem); }

.media-showcase {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  gap: 1rem;
  min-height: 50vh;
  margin-bottom: 7rem;
}
.block { border-radius: 2px; }
.block-lg { min-height: 460px; background: linear-gradient(145deg, var(--accent-terracotta), var(--accent-clay)); }
.stack { display: grid; gap: 1rem; }
.block-md { background: linear-gradient(130deg, var(--accent-sage), #7f8c75); }
.block-sm { background: linear-gradient(130deg, var(--accent-sand), #b9a086); }

.marquee-section { margin: 2.5rem 0 7rem; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); padding: 2rem 0; }
.marquee-row { overflow: hidden; white-space: nowrap; }
.marquee-track {
  display: inline-flex;
  gap: 2rem;
  min-width: max-content;
  will-change: transform;
}
.marquee-item {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: clamp(1.4rem, 2.8vw, 2.3rem);
  letter-spacing: 0.01em;
}

.about { display: grid; grid-template-columns: 1fr 1.2fr; gap: 3rem; margin-bottom: 4rem; }
.about h2 { font-size: clamp(2.2rem, 5vw, 4.3rem); }
.about p { color: var(--muted); max-width: 52ch; }

.editorial {
  width: min(100%, 860px);
  margin: 3.5rem auto 5rem;
  padding: 0 1rem;
}
.editorial h1 { font-size: clamp(2.4rem, 8vw, 5.2rem); margin-bottom: 2rem; }
.editorial p { font-size: clamp(1.06rem, 1.3vw, 1.22rem); color: #39342f; margin: 0 0 1.3rem; }
.editorial .signature { margin-top: 2.4rem; font-family: 'Playfair Display', Georgia, serif; font-size: 1.4rem; }

.services-wrap { margin: 4rem 0 5rem; }
.services-wrap h1 { font-size: clamp(2.6rem, 7vw, 5.6rem); margin-bottom: 1.5rem; }
.services-wrap .lead { max-width: 70ch; color: var(--muted); margin-bottom: 3rem; }
.divider { border-top: 1px solid var(--line); margin: 3rem 0; }
.service-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 2rem; }
.service-card h2 { font-size: clamp(1.6rem, 3vw, 2.4rem); margin-bottom: 0.9rem; }
.service-card p { color: var(--muted); }

.clients-wrap { margin: 4rem 0 5rem; }
.clients-wrap h1 { font-size: clamp(3rem, 9vw, 7rem); margin-bottom: 0.5rem; }
.clients-wrap .sub { color: var(--muted); margin-bottom: 2.5rem; }
.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 2rem 2.3rem;
}
.client-item h3 { font-size: clamp(1.4rem, 2.3vw, 2rem); margin-bottom: 0.4rem; }
.client-item p { margin: 0; color: var(--muted); }

.contact-hero { margin: 10vh 0 8vh; }
.contact-hero h1 {
  font-size: clamp(5rem, 24vw, 20rem);
  line-height: 0.85;
  letter-spacing: -0.03em;
}
.contact-links {
  display: flex;
  gap: 2rem;
  flex-wrap: wrap;
  font-size: clamp(1rem, 2vw, 1.35rem);
  margin-bottom: 3rem;
}
.contact-links a { border-bottom: 1px solid var(--text); padding-bottom: 0.2rem; }

@media (max-width: 980px) {
  .hero, .media-showcase, .about, .service-grid, .clients-grid { grid-template-columns: 1fr; }
  .hero { gap: 2rem; margin-top: 2rem; }
  .block-lg { min-height: 320px; }
}

@media (max-width: 760px) {
  .site-wrap { padding: 0 1.2rem 3rem; }
  .nav-links { display: none; }
  .menu-toggle { display: block; }
}
